PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,verified_at INTEGER NOT NULL);
CREATE TABLE otp_challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used_at INTEGER);
CREATE TABLE auth_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),access_hash TEXT NOT NULL UNIQUE,refresh_hash TEXT NOT NULL UNIQUE,access_expires_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at INTEGER NOT NULL,audio_days INTEGER NOT NULL DEFAULT 30,content_days INTEGER NOT NULL DEFAULT 90,revision INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER);
CREATE TABLE memberships(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),status TEXT NOT NULL CHECK(status IN ('active','revoked')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE membership_invites(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),email TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE meetings(workspace_id TEXT NOT NULL REFERENCES workspaces(id),id TEXT NOT NULL,creator_id TEXT NOT NULL REFERENCES users(id),meet_code TEXT NOT NULL,title TEXT NOT NULL,timezone TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('private','workspace')),state TEXT NOT NULL,reason TEXT,revision INTEGER NOT NULL DEFAULT 1,consent_version TEXT NOT NULL,consent_at INTEGER NOT NULL,duration_seconds INTEGER NOT NULL,created_at INTEGER NOT NULL,deleted_at INTEGER,PRIMARY KEY(workspace_id,id));
CREATE UNIQUE INDEX meetings_active_code ON meetings(workspace_id,meet_code) WHERE deleted_at IS NULL AND state IN ('queued','starting','joining','waiting_for_admission','recording','stopping');
CREATE INDEX meetings_cursor ON meetings(workspace_id,created_at DESC,id DESC);
CREATE TABLE meeting_grants(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,user_id TEXT NOT NULL,permission TEXT NOT NULL CHECK(permission IN ('read','edit')),PRIMARY KEY(workspace_id,meeting_id,user_id),FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id),FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE capture_sessions(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,id TEXT NOT NULL,epoch INTEGER NOT NULL,state TEXT NOT NULL,completeness TEXT NOT NULL DEFAULT 'partial',heartbeat_at INTEGER,deadline INTEGER NOT NULL,stopped_at INTEGER,image_digest TEXT,PRIMARY KEY(workspace_id,meeting_id,id),FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id));
CREATE TABLE recording_chunks(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,session_id TEXT NOT NULL,sequence INTEGER NOT NULL,r2_key TEXT NOT NULL UNIQUE,checksum TEXT NOT NULL,bytes INTEGER NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,codec TEXT NOT NULL,PRIMARY KEY(workspace_id,meeting_id,session_id,sequence),FOREIGN KEY(workspace_id,meeting_id,session_id) REFERENCES capture_sessions(workspace_id,meeting_id,id));
CREATE TABLE transcripts(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,version INTEGER NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(workspace_id,meeting_id,version),FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id));
CREATE TABLE transcript_segments(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,version INTEGER NOT NULL,id TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,speaker TEXT,text TEXT NOT NULL,PRIMARY KEY(workspace_id,meeting_id,version,id),FOREIGN KEY(workspace_id,meeting_id,version) REFERENCES transcripts(workspace_id,meeting_id,version));
CREATE TABLE minutes(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,version INTEGER NOT NULL,transcript_version INTEGER NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',PRIMARY KEY(workspace_id,meeting_id,version),FOREIGN KEY(workspace_id,meeting_id,transcript_version) REFERENCES transcripts(workspace_id,meeting_id,version));
CREATE TABLE action_items(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,owner_id TEXT,due_date TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','complete')),citations TEXT NOT NULL DEFAULT '[]',reviewed_at INTEGER,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,meeting_id,id),FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id),FOREIGN KEY(workspace_id,owner_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE conversations(workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,id TEXT NOT NULL,scope TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE messages(workspace_id TEXT NOT NULL,conversation_id TEXT NOT NULL,id TEXT NOT NULL,role TEXT NOT NULL,body TEXT NOT NULL,citations TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,conversation_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id));
CREATE TABLE usage_reservations(workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,dispatch_key TEXT NOT NULL,reserved_seconds INTEGER NOT NULL,settled_seconds INTEGER,state TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,dispatch_key),FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id));
CREATE TABLE outbox(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,completed_at INTEGER,FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id));
CREATE TABLE deletion_jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,meeting_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,FOREIGN KEY(workspace_id,meeting_id) REFERENCES meetings(workspace_id,id));
CREATE TABLE audit_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,kind TEXT NOT NULL,object_id TEXT NOT NULL,created_at INTEGER NOT NULL);
